import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new HZSShufflesCards().solve(in, out);
        out.close();
    }

    static class HZSShufflesCards {
        static final long MOD = 998244353L;
        long[] fact;
        long[] invFact;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int total = n + m;

            fact = new long[total + 1];
            invFact = new long[total + 1];
            fact[0] = 1;
            for (int i = 1; i <= total; i++) {
                fact[i] = fact[i - 1] * i % MOD;
            }
            invFact[total] = inverse(fact[total]);
            for (int i = total; i >= 1; i--) {
                invFact[i - 1] = invFact[i] * i % MOD;
            }

            long phaseSize = 1;
            long cur = 1;
            for (int i = 0; cur != 0; i++) {
                cur = cur * (n - i) % MOD * inverse(n + m - i) % MOD;
                phaseSize = add(phaseSize, cur);
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long term = ncr(n, k);
                term = term * ((long) m + k) % MOD;
                term = term * inverse(k) % MOD;
                term = term * phaseSize % MOD;
                if ((k & 1) == 1) {
                    answer = add(answer, term);
                } else {
                    answer = subtract(answer, term);
                }
            }
            out.println(answer);
        }

        long ncr(int n, int r) {
            if (r < 0 || r > n) return 0;
            return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
        }

        long inverse(long a) {
            long b = MOD;
            long x0 = 1;
            long x1 = 0;
            while (b != 0) {
                long q = a / b;
                long tmp = a - q * b;
                a = b;
                b = tmp;
                tmp = x0 - q * x1;
                x0 = x1;
                x1 = tmp;
            }
            if (a != 1) throw new AssertionError();
            x0 %= MOD;
            if (x0 < 0) x0 += MOD;
            return x0;
        }

        long add(long a, long b) {
            long v = a + b;
            if (v >= MOD) v -= MOD;
            return v;
        }

        long subtract(long a, long b) {
            long v = a - b;
            if (v < 0) v += MOD;
            return v;
        }
    }

    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
